--- Returns a colour with a custom alpha, e.g. C.rgba("primary", 0.35)
---@param name string
---@param alpha number 0.0 - 1.0
---@return string
function C.rgba(name, alpha)
    local hex = C.hex[name]
    if not hex then return "rgba(ffffffff)" end
    local a = math.max(0, math.min(255, math.floor((alpha or 1) * 255 + 0.5)))
    return string.format("rgba(%s%02x)", (hex:gsub("#", "")), a)
end

--- Ready-made gradient for col.active_border
---@param a string
---@param b string
---@param angle integer
function C.gradient(a, b, angle)
    return { colors = { C[a], C[b] }, angle = angle or 45 }
end

return C
